const finance = window.financeDemo;
const root = document.documentElement;
const filters = document.querySelector('#loanFilters');
function setTheme(theme) { root.dataset.theme = theme; const button = document.querySelector('.theme-button'); const dark = theme === 'dark'; button.setAttribute('aria-pressed', String(dark)); button.querySelector('.theme-label').textContent = dark ? 'Modo claro' : 'Modo oscuro'; localStorage.setItem('pw-theme', theme); }
function label(status) { return ({ overdue: 'Vencido', 'due-soon': 'Próximo a vencer', active: 'Activo', paid: 'Pagado' })[status] || 'Activo'; }
function render() { const data = new FormData(filters); const search = data.get('search').trim().toLowerCase(); const order = { overdue: 0, 'due-soon': 1, active: 2, paid: 3 }; const loans = finance.loans.filter((loan) => (!data.get('status') || loan.status === data.get('status')) && (!search || `${loan.counterparty} ${loan.label}`.toLowerCase().includes(search))).sort((a, b) => order[a.status] - order[b.status] || a.dueDate.localeCompare(b.dueDate)); document.querySelector('#loanCount').textContent = `${loans.length} préstamo${loans.length === 1 ? '' : 's'}`; document.querySelector('#loanRows').innerHTML = loans.map((loan) => `<tr><td><strong>${loan.counterparty}</strong><small>${loan.label}</small></td><td>${loan.direction === 'received' ? 'Recibido' : 'Otorgado'}</td><td class="price">${finance.formatMoney(loan.balance)}</td><td>${finance.formatMoney(loan.nextInstallment)}</td><td>${loan.dueDate}</td><td><span class="status-badge is-${loan.status}">${label(loan.status)}</span></td><td><a class="finance-link" href="loan-detail.html?id=${loan.id}">Ver detalle</a></td></tr>`).join(''); document.querySelector('#loanEmpty').hidden = loans.length > 0; }
setTheme(localStorage.getItem('pw-theme') || 'light'); document.querySelector('.theme-button').addEventListener('click', () => setTheme(root.dataset.theme === 'dark' ? 'light' : 'dark')); filters.addEventListener('input', render); filters.addEventListener('change', render); render();
